"""Final evidence report: never merge failed old studies into a new positive result."""
import csv,html,json,shutil,sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from goalpilot.engine import atomic_json
from evaluation.native_goals.report import report
from tools.audit_native_goals import audit
ROOT=Path(__file__).resolve().parents[1]


def build(output):
    output=Path(output).resolve();original=report(output);a=audit(output);m=original['protocol']
    corrected=None;data=original
    rows=[json.loads(p.read_text())for item in m['order']if(p:=output/'trials'/item['id']/'record.json').exists()]
    if(output/'fairness/oracle-erratum.json').exists():
        from tools.corrected_validation import summarize
        corrected=summarize(output);data=corrected['measurements'];rows=corrected['corrected_rows']
        qualified=(corrected['prospective_worker_completion_advantage_observed']and data['complete']and data['quality_losses']==0 and a['quality_integrity_verified'])
    else:qualified=data['primary_completion_advantage_observed']and a['quality_integrity_verified']
    previous=ROOT/'reports/ambitious-live-001';oldm=json.loads((previous/'protocol.json').read_text());oldrows=[json.loads(p.read_text())for x in oldm['order']if(p:=previous/'trials'/x['id']/'record.json').exists()]
    rescue=json.loads((ROOT/'reports/audit-rescue-001/result.json').read_text());replay=json.loads((ROOT/'reports/probe-context-replay-001/report.json').read_text())
    old_tokens=sum(r['usage']['total_tokens']for r in oldrows);smoke_tokens=0
    for name in('native-goal-smoke-001','native-goal-smoke-002'):
        r=json.loads((ROOT/'reports'/name/'result.json').read_text())['result'];u=r.get('usage')or{};smoke_tokens+=u.get('input_tokens',0)+u.get('output_tokens',0)
    costs={'original_incomplete_study_known_tokens':old_tokens,'two_technical_smokes_known_tokens':smoke_tokens,'exposed_rescue_new_tokens_only':rescue['new_usage']['total_tokens'],'new_native_comparison_known_tokens':a['known_token_lower_bound']}
    costs['iteration_known_token_lower_bound']=sum(costs.values())
    result={'qualified_completion_advantage_observed':bool(qualified),'measurement':data,'original_measurement':original,'original_primary_claim_allowed':corrected is None,'corrected_analysis':corrected,'audit':a,'development_costs':costs,'earlier_failure':{'planned':12,'actual':len(oldrows),'status':'stopped-for-futility-not-preregistered','paired_flowdesk_direct_success':True,'paired_flowdesk_goalpilot_success':False,'both_artifacts_correct':True},'development_recovery':rescue,'verification_only_replay':replay,
    'interpretation':'Only the new paired study can support its own descriptive criterion. The early-stopped old failure and exposed-case rescue are retained, never rescored/replaced or pooled into success. Two related synthetic scopes do not prove population benefit or personal satisfaction.'}
    atomic_json(ROOT/'reports/native-goals-proof.json',result)
    d,g=(data['groups'][k]for k in('native_goal','goalpilot'));esc=html.escape
    changes={k:100*(g[k]/d[k]-1)if data['complete']and d[k]and (k=='seconds'or d['usage_complete']and g['usage_complete'])else None for k in('seconds','reported_tokens','uncached_input_plus_output')}
    result['total_resource_changes_percent']=changes
    if d['completed_goals']and g['completed_goals']and data['complete']:
        result['per_delivered_goal_savings_percent']={k:100*(1-(g[k]/g['completed_goals'])/(d[k]/d['completed_goals']))if k=='seconds'or d['usage_complete']and g['usage_complete']else None for k in('seconds','reported_tokens','uncached_input_plus_output')}
    atomic_json(ROOT/'reports/native-goals-proof.json',result)
    title='Un avantage de conclusion observé sur ces objectifs.'if qualified else'Un avantage de conclusion reste non démontré.'
    if not data['complete']:title='La comparaison native est incomplète ; aucun gain qualifié.'
    table=''.join(f"<tr><td>{esc(r['case'])}</td><td>{'Codex /goal'if r['mode']=='native_goal'else'GoalPilot'}</td><td>{esc(r['status'])}</td><td>{'oui'if r['success']else'non'}</td><td>{sum(j['passed']for j in r['judgments'])}/{len(r['judgments'])}</td><td>{r['seconds']:.2f}</td><td>{esc(', '.join(sorted({j['id']for j in r['judgments']if not j['passed']})))}</td></tr>"for r in rows)
    metrics=''.join(f'<tr><td>{label}</td><td>{d[key]:,}</td><td>{g[key]:,}</td></tr>'for key,label in [('reported_tokens','Tokens rapportés connus'),('uncached_input_plus_output','Entrée hors cache + sortie connues')])
    page=f'''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GoalPilot — vrais goals, résultats</title><style>body{{max-width:1120px;margin:auto;padding:36px 20px;background:#101b2b;color:#eef4fb;font:17px/1.65 system-ui}}h1{{line-height:1.15}}.lead{{font-size:24px}}.box{{padding:22px;background:#1d3149;border-radius:12px;margin:25px 0}}table{{border-collapse:collapse;width:100%;font-size:15px}}th,td{{padding:12px 9px;text-align:left;border-bottom:1px solid #3b5067}}a{{color:#96dfc9}}.scroll{{overflow:auto}}pre{{white-space:pre-wrap;overflow-wrap:anywhere;background:#1d3149;padding:20px;border-radius:12px}}</style><p>GOALPILOT {esc(m['product_version'])} · COMPARAISON AVEC LE VRAI /GOAL</p><h1>{title}</h1><p class="lead">Goals livrés et validés : <strong>{g['completed_goals']}/{g['runs']} avec GoalPilot</strong>, contre <strong>{d['completed_goals']}/{d['runs']} avec le /goal natif</strong>.</p><div class="box">Un succès exige tous les groupes cachés corrects et une clôture normale. Pour le natif, le goal doit réellement atteindre « complete » et son dernier tour être terminé. Un simple message « fini » ne suffit pas. Les quatre exécutions doivent être présentes. À cause de l’erratum décrit ci-dessous, le critère brut original n’est pas utilisé comme preuve ; le gain qualifié doit être confirmé sur le second objectif, évalué après fixation de la correction.</div><div class="scroll"><table><tr><th>Objectif</th><th>Mode</th><th>Statut</th><th>Livré</th><th>Groupes</th><th>Secondes</th><th>Échecs</th></tr>{table}</table></div><p>Paires gagnées : {data['quality_wins']}. Perdues : {data['quality_losses']}. Code correct indépendamment de la clôture : {d['artifact_successes']} côté natif, {g['artifact_successes']} côté GoalPilot. Cette distinction empêche de présenter une clôture récupérée comme un gain de qualité de code.</p><h2>Correction du juge, conservée séparément</h2><p>Le juge original exigeait de refuser un graphe vide sans que le contrat public le demande. Cet écart ne compte pas comme avantage. Les scores bruts restent inchangés ; les chiffres affichés utilisent une analyse séparée qui retire uniquement ce cas non spécifié. Pour le premier noyau, cette correction est rétrospective. Son code et sa règle ont été figés avant le démarrage des deux essais du second objectif d’automatisation. Un gain qualifié ici exige donc aussi un gain sur ce second objectif, et aucune perte appariée dans l’analyse corrigée.</p><h2>Quels goals ?</h2><p>Un moteur de workflows complet : graphes/révisions, workers et leases, retries, annulation, artifacts, rétention, schedules, sauvegarde/restauration, CLI et HTTP (16 opérations). Puis une extension d’automatisation avec de vrais workers exécutant emit, sum, join, collect, artifact et fail, y compris branches indépendantes, concurrence et reprise. Les deux périmètres partagent le même noyau : ils sont corrélés, pas deux projets indépendants.</p><h2>Coûts</h2><table><tr><th>Mesure</th><th>/goal natif</th><th>GoalPilot</th></tr>{metrics}</table><p>Consommation complète : natif {d['usage_complete']}, GoalPilot {g['usage_complete']}. Les valeurs incomplètes sont des bornes inférieures ; aucune économie totale de tokens ne peut en être tirée. Le budget est de 900 secondes par essai, avec le même modèle gpt-6.1-sol. Les continuations natives sont toutes écoutées et mesurées, au lieu de couper après la première réponse finale.</p><h2>Les échecs de développement restent visibles</h2><p>La première version 0.5.0 a été arrêtée après 3 essais sur 12, une fois son critère sans régression rendu impossible. Sur le support, les deux codes étaient corrects, mais GoalPilot a abandonné sa revue en gardant 223 secondes disponibles. L’arrêt anticipé n’était pas préenregistré : cette étude reste une déviation et un échec, jamais une réussite comparative.</p><p>La reprise 0.5.1 a conservé sept probes, puis généré la dernière. Un défaut de contexte d’import de ce vérificateur a entraîné trois appels de code inutiles et un nouvel échec de clôture. La version 0.5.2 corrige l’environnement d’exécution des probes gelés, sans éditer leurs assertions. Le rejeu local donne 9/9 contrôles, sans API ; ce diagnostic rétrospectif n’est pas une nouvelle réussite réelle.</p><p>Deux essais techniques ont validé la vraie API /goal. Le premier a repéré une écoute interrompue trop tôt ; le garde-fou des compteurs a empêché le lancement de l’étude. Le second atteint une vraie fin de goal et une fin de tour avec consommation complète. Leurs coûts restent séparés des scores.</p><h2>Limites et preuves</h2><p>Ces objectifs sont synthétiques et leurs contrats détaillés. Les résultats ne prouvent pas une amélioration générale sur tes objectifs personnels de plusieurs heures. Les deux conditions utilisent le même sandbox Codex ; sa restriction de socket peut bloquer une vérification native alors que les probes hôte fonctionnent. Les sources et critères ont été figés avant les appels ; aucun juge caché ne fournit de corrections. L’audit des marqueurs de commandes ne constitue pas une observation exhaustive du système de fichiers.</p><p>Coût connu de toute cette itération : <strong>au moins {costs['iteration_known_token_lower_bound']:,} tokens rapportés</strong>. Les consommations historiques réutilisées dans la reprise ne sont pas facturées une seconde fois dans ce calcul. Aucun quota d’abonnement exact n’est déduit.</p><p><a href="native-goals-live-001/report.html">Chaque exécution</a> · <a href="native-goals-live-001/protocol.json">Protocole figé</a> · <a href="native-goals-live-001/trials.csv">CSV</a> · <a href="native-goals-proof.json">Données et audits</a> · <a href="ambitious-proof.html">Étude 0.5.0 échouée</a> · <a href="probe-context-replay-001/report.json">Rejeu 9/9 sans API</a></p></html>'''
    if corrected:
        fields=['id','case','mode','status','normal_exit','original_success','corrected_success','corrected_artifact_success','groups_passed','groups_total','seconds','initiated_model_turns','reported_tokens','cached_input_tokens','uncached_input_plus_output','usage_complete']
        with(output/'corrected-trials.csv').open('w',newline='')as f:
            w=csv.DictWriter(f,fieldnames=fields);w.writeheader()
            for r in rows:w.writerow({k:r[k]for k in('id','case','mode','status','normal_exit','original_success','seconds')}|{'corrected_success':r['success'],'corrected_artifact_success':r['artifact_success'],'groups_passed':sum(j['passed']for j in r['judgments']),'groups_total':len(r['judgments']),'initiated_model_turns':sum(c['initiated_turns_from_raw']for c in a['calls']if c['id']==r['id']),'reported_tokens':r['usage']['total_tokens'],'cached_input_tokens':r['usage']['cached_input_tokens'],'uncached_input_plus_output':r['usage']['total_tokens']-r['usage']['cached_input_tokens'],'usage_complete':r['usage']['usage_complete']})
        page=page.replace('<a href="native-goals-live-001/trials.csv">CSV</a>','<a href="native-goals-live-001/corrected-trials.csv">CSV corrigé</a> · <a href="native-goals-live-001/trials.csv">Scores bruts originaux</a>')
        raw_page=output/'report.html';raw=raw_page.read_text();raw=raw.replace('<h1>Vrai /goal natif et GoalPilot</h1>','<h1>Scores bruts du protocole original</h1><p><strong>Ces scores contiennent un critère non écrit sur le graphe vide et ne sont pas utilisés comme preuve.</strong> <a href="../native-goals-proof.html">Analyse corrigée et limites</a>.</p>');raw_page.write_text(raw)
    if all(v is not None for v in changes.values()):
        metrics_note=f'<p><strong>Bilan total : {changes["seconds"]:+.2f} % de temps, {changes["reported_tokens"]:+.2f} % de tokens totaux, {changes["uncached_input_plus_output"]:+.2f} % de tokens hors cache + sortie.</strong> Le gain de clôture est observé ; les trois économies globales ne sont pas établies ensemble.</p>'
        page=page.replace('<h2>Coûts</h2>','<h2>Coûts</h2>'+metrics_note)
    (ROOT/'reports/native-goals-proof.html').write_text(page)
    print(json.dumps({'complete':data['complete'],'qualified':bool(qualified),'groups':data['groups'],'wins':data['quality_wins'],'losses':data['quality_losses'],'known_iteration_token_lower_bound':costs['iteration_known_token_lower_bound']},indent=2));return result


if __name__=='__main__':build(sys.argv[1])
